// <auto-generated />
// Generated from TrussArchBridge03Net and its two LOD archetype geometry assets.
// The metaprogram selected the unique deck-adjacent, x=0-crossing island which spans the 128 m section.
#nullable enable
using System;
using System.Collections.Generic;
using Unity.Mathematics;

namespace BridgePrefabGenerator.Bridges;

/// <summary>
/// Exact vertex membership of the TrussArchBridge03 structure immediately below the road deck.
/// Runtime code consumes this recorded result and performs no bounds, topology or coordinate-band guess.
/// </summary>
internal static class TrussArch03BaseGeometry
{
    private sealed class BaseMap
    {
        internal BaseMap(int vertexCount, int baseVertices, string membership)
        {
            VertexCount = vertexCount;
            BaseVertices = baseVertices;
            Membership = membership;
        }

        internal int VertexCount { get; }
        internal int BaseVertices { get; }
        internal string Membership { get; }
    }

    private static readonly IReadOnlyDictionary<string, BaseMap> Maps =
        new Dictionary<string, BaseMap>(StringComparer.Ordinal)
        {
            ["TrussArchBridge03Net Mesh"] = new BaseMap(
                37416, 6004,
                ""),
            ["TrussArchBridge03Net_LOD1 Mesh"] = new BaseMap(
                30026, 5601,
                ""),
            ["TrussArchBridge03Net_LOD2 Mesh"] = new BaseMap(
                3636, 200,
                ""),
        };

    internal static bool IsRecorded(string? styleId, string? meshName) =>
        string.Equals(styleId, "TrussArch03", StringComparison.Ordinal)
        && !string.IsNullOrEmpty(meshName)
        && Maps.ContainsKey(meshName);

    /// <summary>
    /// Replaces only the recorded deck-base vertices in the generic widened result. The base mapping is
    /// x -> x + sign(x) * delta; y and z remain exactly those of the archetype. The x=0 crossing check
    /// compares only against the origin and validates metadata rather than selecting geometry.
    /// </summary>
    internal static bool TryApply(
        string? meshName,
        float3[] source,
        float3[] genericWidened,
        float delta,
        out float3[] result,
        out int baseVertices,
        out string? error)
    {
        result = genericWidened;
        baseVertices = 0;
        error = null;

        if (string.IsNullOrEmpty(meshName) || !Maps.TryGetValue(meshName, out var map))
        {
            error = "the archetype mesh identity is not present in the generated base map";
            return false;
        }

        if (source.Length != map.VertexCount || genericWidened.Length != source.Length)
        {
            error = string.Format(
                System.Globalization.CultureInfo.InvariantCulture,
                "recorded vertex count {0}, source {1}, widened {2}",
                map.VertexCount,
                source.Length,
                genericWidened.Length);
            return false;
        }

        byte[] membership;
        try
        {
            membership = Convert.FromBase64String(map.Membership);
        }
        catch (Exception exception)
        {
            error = "the generated membership data could not be decoded (" + exception.GetType().Name + ")";
            return false;
        }

        if (membership.Length != (map.VertexCount + 7) / 8)
        {
            error = "the generated membership data has the wrong length";
            return false;
        }

        var reachesLeft = false;
        var reachesRight = false;
        for (var index = 0; index < source.Length; index++)
        {
            if ((membership[index >> 3] & (1 << (index & 7))) == 0) continue;

            baseVertices++;
            if (source[index].x < 0f) reachesLeft = true;
            if (source[index].x > 0f) reachesRight = true;
        }

        if (baseVertices != map.BaseVertices)
        {
            error = string.Format(
                System.Globalization.CultureInfo.InvariantCulture,
                "recorded {0} base vertices but decoded {1}",
                map.BaseVertices,
                baseVertices);
            return false;
        }

        // A deck base must cross x=0. If the recorded vertices do not occupy both sides of the origin,
        // this mesh is rejected as a base and no base transform is written.
        if (!reachesLeft || !reachesRight)
        {
            error = "the recorded component does not cross x=0 and therefore is not a deck base";
            return false;
        }

        var adjusted = (float3[])genericWidened.Clone();
        for (var index = 0; index < source.Length; index++)
        {
            if ((membership[index >> 3] & (1 << (index & 7))) == 0) continue;

            var point = source[index];
            var offset = point.x > 0f ? delta : point.x < 0f ? -delta : 0f;
            adjusted[index] = new float3(point.x + offset, point.y, point.z);
        }

        result = adjusted;
        return true;
    }
}
